name: Flutter quality

on:
  pull_request:
  push:
    branches: [main]

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  quality:
    runs-on: ubuntu-latest
    timeout-minutes: 20
    steps:
      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4
        with:
          submodules: recursive
          fetch-depth: 0
          persist-credentials: false

      - name: Verify pinned Flutter SDK
        shell: bash
        run: |
          test -x flutter/bin/flutter || {
            echo 'Expected the repository-pinned Flutter SDK at ./flutter' >&2
            exit 1
          }
          flutter/bin/flutter --version

      - name: Install dependencies
        run: flutter/bin/flutter pub get --enforce-lockfile

      - name: Check changed Dart formatting
        if: github.event_name == 'pull_request'
        shell: bash
        env:
          BASE_SHA: ${{ github.event.pull_request.base.sha }}
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
        run: |
          mapfile -t paths < <(git diff --name-only --diff-filter=ACMRT "$BASE_SHA" "$HEAD_SHA" -- '*.dart')
          if ((${#paths[@]})); then
            flutter/bin/dart format --output=none --set-exit-if-changed "${paths[@]}"
          fi

      - name: Analyze
        run: flutter/bin/flutter analyze --no-fatal-infos

      - name: Test
        run: flutter/bin/flutter test

  windows-native:
    runs-on: windows-latest
    timeout-minutes: 25
    steps:
      - uses: actions/checkout@fbc6f3992d24b796d5a048ff273f7fcc4a7b6c09 # v5
        with:
          submodules: recursive
          fetch-depth: 0
          persist-credentials: false

      - name: Configure pinned Flutter SDK
        shell: pwsh
        run: |
          flutter in lutter config --enable-windows-desktop --no-analytics
          "$env:GITHUB_WORKSPACE lutter in" | Out-File -FilePath $env:GITHUB_PATH -Encoding utf8 -Append

      - name: Install dependencies
        run: flutter in lutter pub get --enforce-lockfile

      - name: Test Store symbol archive assembly
        shell: pwsh
        run: ./.github/scripts/test-create-store-upload.ps1

      - name: Test Windows native integrations
        run: flutter in lutter test -d windows integration_test/windows_native_smoke_test.dart

